import java.nio.file.Path;
import java.sql.DriverManager;
import liquibase.*;
import liquibase.database.*;
import liquibase.database.jvm.JdbcConnection;
import liquibase.resource.DirectoryResourceAccessor;
/** Actual isolated owner-migrator rollback checks; never invoked against application deployment databases. */
public class NotificationIncrementProbe {
 public static void main(String[] args)throws Exception{if(args.length!=1||!java.util.Set.of("empty","populated").contains(args[0]))throw new IllegalArgumentException();try(var connection=DriverManager.getConnection("jdbc:postgresql://postgres:5432/nigson","nigson_integration_migrator",System.getenv("MIGRATION_PASSWORD"));var resources=new DirectoryResourceAccessor(Path.of("/app/source"))){var database=DatabaseFactory.getInstance().findCorrectDatabaseImplementation(new JdbcConnection(connection));database.setDefaultSchemaName("integration");database.setLiquibaseSchemaName("integration");try(var migration=new Liquibase("services/integration/src/main/resources/db/changelog/master.yaml",resources,database)){migration.setChangeLogParameter("schema.release","BP1");if(args[0].equals("populated")){boolean refused=false;try{migration.rollback(1,new Contexts(),new LabelExpression());}catch(liquibase.exception.LiquibaseException expected){refused=true;}if(!refused)throw new IllegalStateException("POPULATED_ROLLBACK_MUST_REFUSE");try(var statement=connection.createStatement();var rows=statement.executeQuery("SELECT count(*) FROM integration.notification_dispatch")){rows.next();if(rows.getLong(1)!=1)throw new IllegalStateException("POPULATED_ROLLBACK_LOST_EVIDENCE");}System.out.println("PASS: populated notification dispatch rollback refused and preserved evidence");return;}migration.rollback(1,new Contexts(),new LabelExpression());try(var statement=connection.createStatement();var rows=statement.executeQuery("SELECT to_regclass('integration.notification_dispatch') IS NULL")){rows.next();if(!rows.getBoolean(1))throw new IllegalStateException("EMPTY_INCREMENT_ROLLBACK_FAILED");}migration.update(new Contexts(),new LabelExpression());migration.validate();System.out.println("PASS: empty notification dispatch increment actually rolled back/reapplied");}}}
}
